import {flipEndpointLanguage} from './helpers'

export function checkS3Fields(): boolean {
  const bucket = document.getElementById('s3_bucket') as HTMLInputElement
  const oidcAuditlogInputField = document.getElementById('arn_role') as HTMLInputElement
  const authenticationTypeHiddenField = document.getElementById('authentication_type') as HTMLInputElement

  if (authenticationTypeHiddenField?.value === 'oidc_auditlog') {
    return bucket?.value.length > 0 && oidcAuditlogInputField?.value.length > 0
  } else {
    return bucket?.value.length > 0
  }
}

export function toggleS3Form() {
  const accessKeysButton = document.getElementById('s3-access-keys-button') as HTMLButtonElement
  const accessKeyInputDiv = document.getElementById('s3-access-key-input') as HTMLDivElement
  const secretKeyInputDiv = document.getElementById('s3-secret-key-input') as HTMLDivElement

  const oidcAuditlogButton = document.getElementById('s3-oidc-auditlog-button') as HTMLButtonElement
  const oidcAuditlogInputDiv = document.getElementById('s3-oidc-auditlog-input') as HTMLDivElement

  const authenticationTypeHiddenField = document.getElementById('authentication_type') as HTMLInputElement

  const endpointButton = document.getElementsByName('check_button')[0] as HTMLButtonElement
  const saveButton = document.getElementsByName('store_button')[0] as HTMLButtonElement

  const accessKeyInputField = document.getElementById('key_id_secret') as HTMLInputElement
  const secretKeyInputField = document.getElementById('key_secret') as HTMLInputElement
  const oidcAuditlogInputField = document.getElementById('arn_role') as HTMLInputElement

  const show = 'display: block !important'
  const hide = 'display: none !important'

  if (accessKeysButton && oidcAuditlogButton && accessKeyInputDiv && secretKeyInputDiv && oidcAuditlogInputDiv) {
    accessKeysButton.addEventListener('click', () => {
      accessKeysButton.style.color = '#ffffff'
      accessKeysButton.style.backgroundColor = '#2da44e'
      oidcAuditlogButton.style.color = '#24292f'
      oidcAuditlogButton.style.backgroundColor = '#f6f8fa'

      accessKeyInputDiv.setAttribute('style', show)
      secretKeyInputDiv.setAttribute('style', show)
      oidcAuditlogInputDiv.setAttribute('style', hide)

      authenticationTypeHiddenField.value = 'access_keys'

      saveButton.disabled = true
      endpointButton.disabled = true
      oidcAuditlogInputField.value = ''

      flipEndpointLanguage()
    })

    oidcAuditlogButton.addEventListener('click', () => {
      oidcAuditlogButton.style.color = '#ffffff'
      oidcAuditlogButton.style.backgroundColor = '#2da44e'
      accessKeysButton.style.color = '#24292f'
      accessKeysButton.style.backgroundColor = '#f6f8fa'

      oidcAuditlogInputDiv.setAttribute('style', show)
      accessKeyInputDiv.setAttribute('style', hide)
      secretKeyInputDiv.setAttribute('style', hide)

      authenticationTypeHiddenField.value = 'oidc_auditlog'

      saveButton.disabled = true
      endpointButton.disabled = true
      accessKeyInputField.value = ''
      accessKeyInputField.placeholder = ''
      secretKeyInputField.value = ''
      secretKeyInputField.placeholder = ''

      flipEndpointLanguage()
    })
  }
}
